export const MONSTERS = [{"id":"MON-01","name":"Главоглаз","cell":"r1c1","level":1,"life":10,"model":"Главоглаз.obj","ability":"Перед тем как будут сформированы запасы жизней, игрок сбрасывает 1 карту из руки.","trophy":"Один раз за битву: перед тем как будут сформированы запасы жизней, если у вас в руке 1 карта или менее, возьмите 2 карты из своей колоды."},{"id":"MON-02","name":"Гарпия","cell":"r1c2","level":1,"life":12,"model":"Гарпия.obj","ability":"В первый ход битвы игрока его навык сражения временно снижен до 0 (он не берёт карты за навык сражения, но может брать карты за другие эффекты).","trophy":"Один раз за битву: перед тем как будут сформированы запасы жизней, сбросьте 1 карту из руки, чтобы, после того как будут сформированы запасы жизней, нанести 2 урона."},{"id":"MON-03","name":"Гнездо гулей","cell":"r1c3","level":1,"life":12,"model":"Гуль.obj","ability":"В первый ход битвы игрока из запаса жизни монстра может быть сброшено не более 2 карт (сколько бы урона ни было нанесено).","trophy":"Каждый раз, когда вы заканчиваете ход в водной локации, возьмите 1 эликсир."},{"id":"MON-04","name":"Туманник","cell":"r1c4","level":1,"life":10,"model":"Туманник.obj","ability":"В первый ход монстра игрок, контролирующий его, не выбирает тип атаки. Вместо этого применяется та атака с открытой карты, в результате которой игрок должен будет сбросить наибольшее количество карт.","trophy":"В течение всей битвы: если во время хода противника вы сбросили хотя бы 1 карту из своей колоды из-за его атаки, в конце этого хода противника возьмите 1 карту."},{"id":"MON-05","name":"Гнездо накеров","cell":"r1c5","level":1,"life":11,"model":"Накер.obj","ability":"В течение всей битвы: в конце своего хода битвы игрок берёт на 1 карту меньше, если в его комбинации нет хотя бы 1 карты защитного приёма (зелёной).","trophy":"Один раз за битву: перед тем как будут сформированы запасы жизней, если у вас нет эликсиров, возьмите 2 эликсира."},{"id":"MON-06","name":"Архиспора","cell":"r1c6","level":1,"life":12,"model":"Архиспора.obj","ability":"Чтобы начать битву с этим монстром, игрок должен сбросить 1 эликсир (иначе он не может начать битву).","trophy":"Один раз за битву: если в вашей колоде нет карт, увеличьте свой уровень щита на 1."},{"id":"MON-07","name":"Баргест","cell":"r1c7","level":1,"life":11,"model":"Багрест.obj","ability":"Перед тем как будут сформированы запасы жизней, игрок понижает свой уровень щита на 1.","trophy":"Один раз за битву: сбросьте 2 неиспользованных эликсира, чтобы нанести 1 урон и взять 1 карту."},{"id":"MON-08","name":"Бес","cell":"r2c1","level":2,"life":13,"model":"Бес.obj","ability":"В течение всей битвы: эффекты карт атакующих Знаков (фиолетовых) не действуют (их по-прежнему можно использовать в комбинации, чтобы продлить её).","trophy":"В течение всей битвы: если в вашей комбинации есть хотя бы 1 карта защитного Знака (жёлтая), в конце своего хода битвы возьмите на 2 карты больше."},{"id":"MON-09","name":"Грифон","cell":"r2c2","level":2,"life":15,"model":"Гриффон.obj","ability":"В течение всей битвы: в конце своего хода битвы игрок берёт на 1 карту меньше (но не менее 1 карты).","trophy":"Один раз за битву: в свой первый ход битвы бросьте кубик: - 1–2: Нет эффекта. - 3–5: Нанесите 2 урона. - 6: Нанесите 3 урона."},{"id":"MON-10","name":"Виверна","cell":"r2c3","level":2,"life":15,"model":"Виверна.obj","ability":"В конце первого хода монстра игрок сбрасывает 1 случайную карту из руки.","trophy":"Один раз за битву: сбросьте 1 карту из руки, чтобы взять 1 любую карту из своего сброса."},{"id":"MON-11","name":"Полуденница","cell":"r2c4","level":2,"life":14,"model":"Полуденница.obj","ability":"В течение всей битвы: уровень щита игрока не может быть увеличен более чем на 1 за ход битвы (последующие увеличения игнорируются).","trophy":"Один раз за битву: сбросьте 1 неиспользованный эликсир, чтобы взять 2 карты."},{"id":"MON-12","name":"Волколак","cell":"r2c5","level":2,"life":14,"model":"Волколак.obj","ability":"Перед тем как будут сформированы запасы жизней, игрок понижает свой уровень щита на 2.","trophy":"Каждый раз, когда вы заканчиваете фазу II в горной локации, в фазу III возьмите из своей колоды на 1 карту больше."},{"id":"MON-13","name":"Стрыга","cell":"r2c6","level":3,"life":18,"model":"Стрыга.obj","ability":"Перед тем как будут сформированы запасы жизней, игрок понижает свой уровень щита на 1 за каждую карту в своей руке.","trophy":"В течение всей битвы: каждая карта мощной атаки (красная) в вашей комбинации дополнительно наносит 1 урон."},{"id":"MON-14","name":"Брукса","cell":"r2c7","level":3,"life":17,"model":"Брукса.obj","ability":"В течение всей битвы: если на начало хода монстра в его запасе жизни осталось 2 карты или меньше, его атака на этом ходу дополнительно наносит 2 урона.","trophy":"Один раз за битву: сбросьте 1 карту из руки, чтобы взять 5 карт."},{"id":"MON-15","name":"Леший","cell":"r3c1","level":3,"life":19,"model":"Леший.obj","ability":"В течение всей битвы: навык защиты игрока временно снижен на 1 (понизьте уровень щита, если требуется).","trophy":"Один раз за битву: после открытия карты из запаса жизни монстра, вы можете изменить тип атаки (удар или укус)."},{"id":"MON-16","name":"Гнездо утопцев","cell":"r3c2","level":1,"life":10,"model":"Утопленники.obj","ability":"После того как будут сформированы запасы жизней, игрок выбирает и сбрасывает 1 любую карту из своей колоды (перемешайте колоду после этого).","trophy":"Один раз за битву: перед тем как будут сформированы запасы жизней, увеличьте свой уровень щита на 2."},{"id":"MON-17","name":"Экимма","cell":"r3c3","level":1,"life":12,"model":"Экимма.obj","ability":"После того как будут сформированы запасы жизней, если у игрока нет жетона следа этого монстра, он сбрасывает 1 карту из руки.","trophy":"Один раз за битву: перед тем как будут сформированы запасы жизней, возьмите 1 эликсир."},{"id":"MON-18","name":"Гнилец","cell":"r3c4","level":1,"life":11,"model":"Гнилец.obj","ability":"После того как монстр побеждён, в эту фазу III игрок берёт только 1 карту из своей колоды. Это значение не может быть изменено другими эффектами.","trophy":"Один раз за битву: бросьте кубик: - 1–3: Нет эффекта. - 4–6: Нанесите 1 урон."},{"id":"MON-19","name":"Покаянник","cell":"r3c5","level":2,"life":14,"model":"Покаянник.obj","ability":"В первый ход битвы игрока, если у него нет жетона следа этого монстра, весь наносимый игроком урон игнорируется.","trophy":"Каждый раз, когда вы заканчиваете фазу II в водной локации, в фазу III возьмите из своей колоды на 1 карту больше."},{"id":"MON-20","name":"Водная баба","cell":"r3c6","level":2,"life":15,"model":"Водная баба.obj","ability":"В течение всей битвы: игрок может использовать не более 1 эликсира (за всю битву).","trophy":"Каждый раз, когда вы заканчиваете ход, возьмите 1 золото."},{"id":"MON-21","name":"Мантикора","cell":"r3c7","level":2,"life":14,"model":"Мантикора.obj","ability":"В течение всей битвы: когда монстр наносит урон, этот урон снижается на 1, но игрок дополнительно сбрасывает 1 случайную карту из руки.","trophy":"Один раз за битву: сбросьте 2 золота, чтобы взять 1 любую карту из своего сброса."},{"id":"MON-22","name":"Полуночница","cell":"r4c1","level":2,"life":14,"model":"Полуночница.obj","ability":"В первый ход битвы игрока в качестве первой карты комбинации, он разыгрывает случайную карту из руки.","trophy":"Один раз за битву: в свой первый ход битвы бросьте кубик: - 1: Нет эффекта. - 2–3: Возьмите 1 карту. - 4–5: Возьмите 2 карты. - 6: Возьмите 3 карты."},{"id":"MON-23","name":"Пряха","cell":"r4c2","level":2,"life":14,"model":"Пряха.obj","ability":"Перед тем как будут сформированы запасы жизней, игрок понижает свой навык защиты на 1 (и уровень щита, если требуется).","trophy":"Один раз за битву: перед тем как будут сформированы запасы жизней, поменяйте 1 карту из руки на 1 любую карту из своей колоды (но не из сброса)."},{"id":"MON-24","name":"Шептуха","cell":"r4c3","level":2,"life":15,"model":"Шептуха.obj","ability":"В течение всей битвы: закончив применять эффекты комбинации, в которой есть хотя бы 1 карта защитного Знака (жёлтая), игрок понижает свой уровень щита на 2.","trophy":"Один раз за ход: в фазу I переместитесь на расстояние в 2 локации, сбросив 1 карту с тем же символом местности, что и у локации куда вы перемещаетесь (не останавливайтесь в первой локации и игнорируйте её тип местности)."},{"id":"MON-25","name":"Кладбищенская баба","cell":"r4c4","level":2,"life":13,"model":"Кладбищенская баба.obj","ability":"В первый ход монстра распределение урона, полученного игроком, начинается со сброса карт из его руки (если их недостаточно, оставшийся урон распределяется по обычным правилам: снижение уровня щита, сброс карт из колоды).","trophy":"Каждый раз, когда вы должны взять эликсир, вместо этого посмотрите 3 верхние карты из колоды эликсиров и возьмите 1 из них. Остальные просмотренные карты поместите под низ колоды эликсиров."},{"id":"MON-26","name":"Кухарка","cell":"r4c5","level":3,"life":17,"model":"Кухарка.obj","ability":"В течение всей битвы: урон от комбинаций, в которых есть хотя бы 1 карта защитного приёма (зелёная) или защитного Знака (жёлтая), снижен на 1.","trophy":"Один раз за битву: если в вашей колоде нет карт, увеличьте свой уровень щита на 3."},{"id":"MON-27","name":"Жагница","cell":"r4c6","level":3,"life":18,"model":"Жагница.obj","ability":"В первый ход битвы игрока он может нанести только 1 урон (последующий урон игнорируется).","trophy":"Один раз за битву: в начале своего первого хода битвы возьмите 1 карту и нанесите 1 урон."},{"id":"MON-28","name":"Сколопендроморф","cell":"r4c7","level":3,"life":18,"model":"Сколопендроморф.obj","ability":"В течение всей битвы: урон от комбинаций, в которых есть хотя бы 1 карта быстрой атаки (синяя), снижен на 1.","trophy":"Один раз за битву: возьмите 1 любую карту из своего сброса."},{"id":"MON-29","name":"Кащей","cell":"r5c1","level":3,"life":16,"model":"Кащей.obj","ability":"В течение всей битвы: эффекты в углах карт атакующих Знаков (фиолетовых) и на фиолетовых связях для комбинаций игнорируются (в том числе чародеи не могут тратить энергию на дополнительные эффекты фиолетовых карт).","trophy":"Один раз за битву: в битве с монстром, перед его первым ходом, получите 3 единицы барьера."},{"id":"MON-30","name":"Тролль","cell":"r5c2","level":3,"life":19,"model":"Тролль.obj","ability":"В первый ход монстра его атака дополнительно наносит 3 урона.","trophy":"Один раз за битву: в свой ход битвы, если у вас в колоде не осталось карт, нанесите 2 урона."},{"id":"MON-31","name":"Сирена","cell":"r5c3","level":1,"life":10,"model":"Сирены.obj","ability":"В течение всей битвы: максимум карт в руке игрока равен 3 (сбросьте лишние карты сразу же после того как будут сформированы запасы жизней).","trophy":"В фазу III, получая новую карту из ряда, вместо оплаты её стоимости вы можете сбросить из руки 1 карту с символом водной местности."}];
